function extractLabels(text) {
  if (!text) return [];
  const lines = text.split("\n");
  const labels = [];
  for (const line of lines) {
    const match = line.match(/^[-•*#]\s*(.+)$/);
    if (match) {
      const label = match[1].replace(/[:\d].*$/, "").trim();
      if (label.length > 2 && label.length < 50) {
        labels.push(label);
      }
    }
  }
  return labels.slice(0, 10);
}
