async function analyzeAndOptimize(roleId, domain, currentPrompt) {
  const successes = await searchMemory(`success ${domain}`, {
    domain,
    kinds: ["pattern"],
    limit: 10
  });
  const failures = await searchMemory(`failure ${domain}`, {
    domain,
    kinds: ["lesson"],
    limit: 5
  });
  if (successes.length < 3) {
    return null;
  }
  const evidence = successes.map(
    (s) => `Task: ${s.title}
Outcome: Success (confidence: ${(s.confidence * 100).toFixed(0)}%)
Key insight: ${s.content.slice(0, 200)}`
  );
  if (failures.length > 0) {
    evidence.push(`
--- Common failure patterns to avoid ---`);
    for (const f of failures) {
      evidence.push(`Pitfall: ${f.title} - ${f.content.slice(0, 150)}`);
    }
  }
  const optimizationPrompt = `B\u1EA1n l\xE0 m\u1ED9t Prompt Engineer chuy\xEAn nghi\u1EC7p. H\xE3y ph\xE2n t\xEDch d\u1EEF li\u1EC7u th\xE0nh c\xF4ng v\xE0 th\u1EA5t b\u1EA1i d\u01B0\u1EDBi \u0111\xE2y, sau \u0111\xF3 \u0111\u1EC1 xu\u1EA5t c\u1EA3i ti\u1EBFn system prompt cho agent role "${roleId}" trong domain "${domain}".

CURRENT SYSTEM PROMPT:
${currentPrompt}

EVIDENCE FROM PAST TASKS:
${evidence.join("\n")}

Y\xCAU C\u1EA6U:
1. Ph\xE2n t\xEDch pattern th\xE0nh c\xF4ng v\xE0 th\u1EA5t b\u1EA1i
2. \u0110\u1EC1 xu\u1EA5t system prompt M\u1EDAI (gi\u1EEF nguy\xEAn c\u1EA5u tr\xFAc, ch\u1EC9 th\xEAm/s\u1EEDa ph\u1EA7n quan tr\u1ECDng)
3. Gi\u1EA3i th\xEDch l\xFD do thay \u0111\u1ED5i
4. \u0110\xE1nh gi\xE1 m\u1EE9c c\u1EA3i thi\u1EC7n d\u1EF1 ki\u1EBFn

Tr\u1EA3 l\u1EDDi theo format:
## ANALYSIS
[ph\xE2n t\xEDch]

## SUGGESTED PROMPT
[system prompt m\u1EDBi]

## REASONING
[l\xFD do]

## EXPECTED IMPROVEMENT
[m\xF4 t\u1EA3 ng\u1EAFn]`;
  try {
    const result = await dispatchTextThroughFabric(optimizationPrompt, void 0, {
      domain: "coding",
      task: "general",
      localFallback: true
    });
    if (result.status !== "completed" || !result.winner?.contentPreview) {
      return null;
    }
    const content = result.winner.contentPreview;
    const suggestedPrompt = extractSection(content, "SUGGESTED PROMPT");
    const reasoning = extractSection(content, "REASONING");
    const expectedImprovement = extractSection(content, "EXPECTED IMPROVEMENT");
    if (!suggestedPrompt) return null;
    return {
      roleId,
      domain,
      currentPrompt,
      suggestedPrompt,
      reasoning: reasoning || "AI-optimized based on success patterns.",
      expectedImprovement: expectedImprovement || "Improved relevance and accuracy.",
      evidence: evidence.slice(0, 3)
    };
  } catch {
    return null;
  }
}
function extractSection(content, sectionName) {
  const regex = new RegExp(`## ${sectionName}\\s*\\n([\\s\\S]*?)(?=## |$)`, "i");
  const match = content.match(regex);
  return match ? match[1].trim() : "";
}

