function getSystemSOPRunbooks() {
  return SOP_CATEGORIES;
}
function calculateSOPComplianceScore() {
  let totalSteps = 0;
  let passedSteps = 0;
  for (const cat of SOP_CATEGORIES) {
    for (const step of cat.steps) {
      totalSteps++;
      if (step.status === "passed") passedSteps++;
    }
  }
  const overallScore = totalSteps > 0 ? Math.round(passedSteps / totalSteps * 100) : 100;
  const status2 = overallScore >= 90 ? "EXCELLENT" : overallScore >= 75 ? "GOOD" : "NEEDS_ATTENTION";
  return {
    overallScore,
    totalSteps,
    passedSteps,
    status: status2
  };
}
