var import_node_child_process2 = require("node:child_process");
var CLI_COMMANDS = {
  antigravity: { command: "antigravity", args: (p) => ["-p", p] },
  claude: { command: "claude", args: (p) => ["-p", p] },
  gemini: { command: "gemini", args: (p) => ["-p", p] }
};
async function runCliAgent(input) {
  const cfg = CLI_COMMANDS[input.cli];
  if (!cfg) throw new Error(`Unknown CLI agent: ${input.cli}`);
  const timeout = input.timeoutMs || 12e4;
  return new Promise((resolve) => {
    const child = (0, import_node_child_process2.spawn)(cfg.command, cfg.args(input.prompt), {
      cwd: input.cwd,
      shell: false,
      timeout
    });
    let stdout = "";
    let stderr = "";
    child.stdout?.on("data", (d) => {
      stdout += String(d);
    });
    child.stderr?.on("data", (d) => {
      stderr += String(d);
    });
    child.on("error", (err) => resolve({ cli: input.cli, success: false, output: "", error: err.message, exitCode: null }));
    child.on("close", (code) => resolve({ cli: input.cli, success: code === 0, output: stdout, error: stderr || void 0, exitCode: code }));
  });
}
async function listAvailableCliAgents() {
  const which = process.platform === "win32" ? "where" : "which";
  const results = [];
  for (const [cli, cfg] of Object.entries(CLI_COMMANDS)) {
    const available = await new Promise((resolve) => {
      (0, import_node_child_process2.execFile)(which, [cfg.command], (err) => resolve(!err));
    });
    results.push({ cli, command: cfg.command, available });
  }
  return results;
}

