  if (role.roleId.includes("cfo") || role.roleId.includes("accountant")) {
    department = "T\xE0i Ch\xEDnh & K\u1EBF To\xE1n";
  } else if (role.roleId.includes("scout") || role.roleId.includes("market")) {
    department = "T\u0103ng Tr\u01B0\u1EDFng & Th\u1ECB Tr\u01B0\u1EDDng";
  } else if (role.roleId.includes("security") || role.roleId.includes("judge")) {
    department = "B\u1EA3o M\u1EADt & Qu\u1EA3n Tr\u1ECB";
  }
  const strengths = [
    `\u0110\u1ED9 ch\xEDnh x\xE1c cao (${Math.round(successRate)}% ho\xE0n th\xE0nh nhi\u1EC7m v\u1EE5)`,
    `Chi ph\xED t\u1ED1i \u01B0u: $${costPerTask.toFixed(3)} / task`,
    `Tu\xE2n th\u1EE7 hi\u1EBFn ph\xE1p an to\xE0n (${roleViolations} vi ph\u1EA1m ranh gi\u1EDBi)`
  ];
  const areasForImprovement = [
    "Ti\u1EBFp t\u1EE5c t\u1ED1i \u01B0u h\xF3a token qua m\xF4 h\xECnh c\u1EE5c b\u1ED9 Ollama",
    "T\u0103ng t\u1ED1c \u0111\u1ED9 ph\u1EA3n h\u1ED3i trong c\xE1c chu\u1ED7i chuy\u1EC1n giao Handoff Chain"
  ];
  const executiveEvaluationText = `${role.roleName} thu\u1ED9c Ban ${department} \u0111\u1EA1t x\u1EBFp lo\u1EA1i ${grade} (\u0110i\u1EC3m t\u1ED5ng h\u1EE3p: ${overallScore}/100). \u0110\xE3 ho\xE0n th\xE0nh ${role.successfulTasksCount} t\xE1c v\u1EE5 v\u1EDBi m\u1EE9c chi ph\xED $${role.currentDailySpendUsd}/ng\xE0y. Ho\u1EA1t \u0111\u1ED9ng xu\u1EA5t s\u1EAFc.`;
  return {
    roleId: role.roleId,
    roleName: role.roleName,
    department,
    authorityLevel: role.authorityLevel,
    grade,
    overallScore,
    metrics: {
      tasksCompleted: role.successfulTasksCount,
      successRatePct: Math.round(successRate),
      dailySpendUsd: Number(role.currentDailySpendUsd.toFixed(2)),
      costPerTaskUsd: Number(costPerTask.toFixed(3)),
      boundaryViolationsCount: roleViolations,
      qualityJudgeScore: role.avgJudgeScore
    },
    strengths,
    areasForImprovement,
    executiveEvaluationText,
    evaluatedAt: (/* @__PURE__ */ new Date()).toISOString()
  };
