function scanLeadsAndProposeFollowups(leadsInput) {
  const roleId = "role_ai_market_scout";
  const permCheck = verifyAgentActionPermission(roleId, "video_marketing", "read");
  if (!permCheck.isAllowed) {
    throw new Error(`AI Market Scout b\u1ECB ch\u1EB7n: ${permCheck.message}`);
  }
  const leads = leadsInput && leadsInput.length > 0 ? leadsInput : SAMPLE_LEADS;
  const suggestions = [];
  for (const lead of leads) {
    let priority = "MEDIUM";
    let recommendedAction = "";
    let pitchAngle = "";
    let conversionProbabilityPct = lead.leadScore;
    if (lead.stage === "negotiation" || lead.leadScore >= 90) {
      priority = "CRITICAL";
      recommendedAction = "G\u1ECDi ch\u1ED1t h\u1EE3p \u0111\u1ED3ng & g\u1EEDi link k\xFD s\u1ED1 h\u1EE3p \u0111\u1ED3ng b\u1EA3n quy\u1EC1n";
      pitchAngle = "Nh\u1EA5n m\u1EA1nh cam k\u1EBFt h\u1ED7 tr\u1EE3 tr\u1EF1c ti\u1EBFp 1-1 t\u1EEB Solo Founder v\xE0 b\u1EA3o h\xE0nh 12 th\xE1ng.";
      conversionProbabilityPct = Math.min(98, lead.leadScore + 5);
    } else if (lead.stage === "demo_requested" || lead.lastContactDaysAgo >= 4) {
      priority = "HIGH";
      recommendedAction = "G\u1EEDi video demo t\xEDnh n\u0103ng chuy\xEAn bi\u1EC7t k\xE8m b\u1EA3ng ph\xE2n t\xEDch ROI";
      pitchAngle = `Tr\u1ECDng t\xE2m v\xE0o gi\u1EA3i ph\xE1p t\u1EF1 \u0111\u1ED9ng h\xF3a cho ng\xE0nh ${lead.industry} gi\xFAp ti\u1EBFt ki\u1EC7m 70% th\u1EDDi gian.`;
    } else {
      priority = "MEDIUM";
      recommendedAction = "G\u1EEDi case study kh\xE1ch h\xE0ng t\u01B0\u01A1ng t\u1EF1 qua Zalo/Email";
      pitchAngle = "Chia s\u1EBB c\xE2u chuy\u1EC7n th\xE0nh c\xF4ng v\xE0 l\u1EDDi ch\u1EE9ng th\u1EF1c t\u1EEB kh\xE1ch h\xE0ng c\xF9ng ng\xE0nh.";
    }
    const suggestion = {
      suggestionId: `sug_${lead.id}_${Date.now().toString(36)}`,
      leadId: lead.id,
      customerName: lead.customerName,
      companyName: lead.companyName,
      priority,
      recommendedAction,
      pitchAngle,
      conversionProbabilityPct,
      suggestedByRole: "AI Market & Trends Scout",
      scoutedAt: (/* @__PURE__ */ new Date()).toISOString()
    };
    suggestions.push(suggestion);
  }
  suggestions.sort((a, b) => {
    const pRank = { CRITICAL: 3, HIGH: 2, MEDIUM: 1 };
    return pRank[b.priority] - pRank[a.priority];
  });
  const highPriorityCount = suggestions.filter((s) => s.priority === "CRITICAL" || s.priority === "HIGH").length;
  recordAIAction({
    agentId: "agent_scout_crm",
    roleId,
    domain: "video_marketing",
    actionType: "CRM_LEAD_SCOUTING_COMPLETED",
    targetResource: "crm_leads_queue",
    outputSummary: `AI Scout \u0111\xE3 qu\xE9t ${leads.length} leads v\xE0 ph\xE1t hi\u1EC7n ${highPriorityCount} c\u01A1 h\u1ED9i ch\u1ED1t deal gi\xE1 tr\u1ECB cao.`,
    permissionCheckPassed: true,
    constitutionalRulePassed: true
  });
  return {
    suggestions,
    totalScanned: leads.length,
    highPriorityCount,
    scoutedBy: "AI Market Scout (Claude / Groq Fast)"
  };
}

