// server/services/languageToolValidator.ts
init_aiActionLedger();
var VIETNAMESE_COMMON_PATTERNS = [
  { pattern: /\b(chẩn đoán|chuẩn đoán)\b/i, correct: "ch\u1EA9n \u0111o\xE1n", note: 'D\xF9ng "ch\u1EA9n \u0111o\xE1n" thay v\xEC "chu\u1EA9n \u0111o\xE1n"' },
  { pattern: /\b(xát nhập|sáp nhập)\b/i, correct: "s\xE1p nh\u1EADp", note: 'D\xF9ng "s\xE1p nh\u1EADp" thay v\xEC "x\xE1t nh\u1EADp"' },
  { pattern: /\b(sơ suất|sơ xuất)\b/i, correct: "s\u01A1 su\u1EA5t", note: 'D\xF9ng "s\u01A1 su\u1EA5t" thay v\xEC "s\u01A1 xu\u1EA5t"' },
  { pattern: /\b(giành giật|dành giật)\b/i, correct: "gi\xE0nh gi\u1EADt", note: 'D\xF9ng "gi\xE0nh gi\u1EADt"' },
  { pattern: /([,.!?;:])([^\s\d])/g, correct: "$1 $2", note: "Thi\u1EBFu d\u1EA5u c\xE1ch sau d\u1EA5u c\xE2u" }
];
function validateTextQuality(text, language = "vi") {
  const reportId = `lt_${Date.now()}_${Math.random().toString(36).substring(2, 6)}`;
  const now = (/* @__PURE__ */ new Date()).toISOString();
  const wordCount = text.trim().split(/\s+/).filter(Boolean).length;
  const characterCount = text.length;
  const issues = [];
  const doubleSpaceMatch = text.match(/  +/g);
  if (doubleSpaceMatch) {
    issues.push({
      message: "Ph\xE1t hi\u1EC7n kho\u1EA3ng tr\u1EAFng th\u1EEBa li\xEAn ti\u1EBFp",
      shortMessage: "Kho\u1EA3ng tr\u1EAFng k\xE9p",
      offset: text.indexOf("  "),
      length: 2,
      errorWord: "  ",
      replacements: [" "],
      ruleCategory: "TYPO"
    });
  }
  if (language === "vi") {
    for (const rule of VIETNAMESE_COMMON_PATTERNS) {
      const match = rule.pattern.exec(text);
      if (match) {
        issues.push({
          message: rule.note,
          shortMessage: "L\u1ED7i ch\xEDnh t\u1EA3 / d\xF9ng t\u1EEB",
          offset: match.index,
          length: match[0].length,
          errorWord: match[0],
          replacements: [rule.correct],
          ruleCategory: "TYPO"
        });
      }
    }
  }
  const deductions = issues.length * 8;
  const qualityScore = Math.max(0, Math.min(100, 100 - deductions));
  const isPublishReady = qualityScore >= 80;
  const report = {
    reportId,
    language,
    characterCount,
    wordCount,
    qualityScore,
    isPublishReady,
    issues,
    validatedAt: now
  };
  recordAIAction({
    agentId: "languagetool_validator",
    roleId: "role_ai_market_scout",
    domain: "video_marketing",
    actionType: `GRAMMAR_VALIDATED:${language}`,
    targetResource: reportId,
    outputSummary: `So\xE1t l\u1ED7i ch\xEDnh t\u1EA3 (${language}): ${wordCount} t\u1EEB, \u0110i\u1EC3m ch\u1EA5t l\u01B0\u1EE3ng: ${qualityScore}/100, ${issues.length} c\u1EA3nh b\xE1o.`,
    permissionCheckPassed: true,
    constitutionalRulePassed: true
  });
  return report;
}

