function handleCompanyPulseSSE(req, res) {
  res.setHeader("Content-Type", "text/event-stream");
  res.setHeader("Cache-Control", "no-cache, no-transform");
  res.setHeader("Connection", "keep-alive");
  res.setHeader("X-Accel-Buffering", "no");
  res.flushHeaders?.();
  const initialSnapshot = getCompanyPulseSnapshot();
  res.write(`event: pulse_snapshot
data: ${JSON.stringify(initialSnapshot)}

`);
  const unsubscribeTelemetry = subscribeTelemetry((event) => {
    res.write(`event: telemetry_event
data: ${JSON.stringify(event)}

`);
  });
  const intervalId = setInterval(() => {
    const pulse = getCompanyPulseSnapshot();
    res.write(`event: pulse_update
data: ${JSON.stringify(pulse)}

`);
  }, 5e3);
  req.on("close", () => {
    clearInterval(intervalId);
    unsubscribeTelemetry();
    res.end();
  });
}

