// server/services/dormant/enterprise-autonomyRouter.ts
function successResponse3(res, data) {
  return res.json({ success: true, ...data });
}
function errorResponse3(res, err, status2 = 500) {
  const message = err instanceof Error ? err.message : String(err);
  return res.status(status2).json({ success: false, error: message });
}
