function generateQuarterlyTaxFiling(quarter = "Q3/2026", totalRevenueVnd = 15e7, totalExpensesVnd = 8e7) {
  const vatOutputVnd = Math.round(totalRevenueVnd * 0.1);
  const vatInputDeductibleVnd = Math.round(totalExpensesVnd * 0.1);
  const netVatPayableVnd = Math.max(0, vatOutputVnd - vatInputDeductibleVnd);
  const profitBeforeTax = Math.max(0, totalRevenueVnd - totalExpensesVnd);
  const estimatedCitVnd = Math.round(profitBeforeTax * 0.2);
  const softwareTaxExemptionVnd = Math.round(estimatedCitVnd * 0.5);
  return {
    quarter,
    vatOutputVnd,
    vatInputDeductibleVnd,
    netVatPayableVnd,
    revenueTaxableVnd: totalRevenueVnd,
    estimatedCitVnd: estimatedCitVnd - softwareTaxExemptionVnd,
    softwareTaxExemptionVnd,
    complianceStatus: "COMPLIANT",
    generatedAt: (/* @__PURE__ */ new Date()).toISOString()
  };
}

