function simulateFundingRound(input) {
  const postMoney = input.preMoneyValuationVnd + input.raisedAmountVnd;
  const dilution = Math.round(input.raisedAmountVnd / postMoney * 1e3) / 10;
  const founderNewOwnership = Math.round(75 * (1 - dilution / 100) * 10) / 10;
  publishSystemEvent({
    eventType: "finance.funding_round_simulated",
    source: "InvestorRelationsEngine",
    department: "finance",
    payload: {
      roundName: input.roundName,
      postMoney,
      dilution
    }
  });
  return {
    postMoneyValuationVnd: postMoney,
    dilutionPercentage: dilution,
    founderNewOwnership
  };
}

